const BUILD_RUNTIME_ROOT: Option<&str> = option_env!("LIFEOS_RUNTIME_ROOT");
const IPC_ALLOWLIST: [&str; 11] = ["capture_record", "get_today", "runtime_status", "confirm_capture_context", "get_context_recovery", "get_context_next_action", "decide_context_next_action", "record_action_result", "assemble_global_ai_context", "get_evidence_backed_understanding", "decide_understanding_feedback"];
const PERSON_ID: &str = "person:synthetic-owner";
const PROJECT_ID: &str = "synthetic-lifeos-product";
const CONTEXT_ID: &str = "ctx:project:synthetic-lifeos-product";
const SOURCE_ID: &str = "SRC-SYN-WORK-001";
const ARTIFACT_VERSION: &str = "ART-SYN-CONTEXT-RECOVERY-001@v1";
const SUFFICIENT_TEXT: &str = "整理 LifeOS Context Recovery 合成验收记录。";
const SUFFICIENT_KEY: &str = "p3-130-capture-001";
const INSUFFICIENT_TEXT: &str = "LifeOS Context Recovery 合成记录。";
const INSUFFICIENT_KEY: &str = "p3-131-insufficient-001";
const EDITED_TEXT: &str = "整理并复核 LifeOS Context Recovery 合成验收记录。";
const RESULT_TEXT: &str = "已完成合成验收记录整理与复核。";
const RULE_ID: &str = "local_rule:p3-131-v1";
const ADAPTER_ID: &str = "offline_synthetic_model:p3-132-v1";
const ADAPTER_VERSION: &str = "p3-132-v1";
const OBSERVATION_TEXT: &str = "当前 Context 已具备继续推进所需的已确认 Evidence。";
const SUGGESTION_TEXT: &str = "继续完成 LifeOS Context Recovery 合成验收记录的复核。";
const UNDERSTANDING_EDITED_TEXT: &str = "继续完成并复核 LifeOS Context Recovery 合成验收记录。";
