// This remains a Project-backed projection.  There is no generic Context, generic
// Action API, Memory body copy, ModelPort, AgentPort, or renderer storage access.
const SCHEMA: &str = r#"
PRAGMA journal_mode = DELETE;
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS captures (
 id TEXT PRIMARY KEY, content TEXT NOT NULL, created_at_ms INTEGER NOT NULL,
 source TEXT NOT NULL CHECK(source='local_capture'), source_id TEXT NOT NULL,
 artifact_version TEXT NOT NULL, idem_key TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS projects (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL, title TEXT NOT NULL, source_id TEXT NOT NULL,
 artifact_version TEXT NOT NULL, source_available INTEGER NOT NULL, generation_current INTEGER NOT NULL,
 tombstoned INTEGER NOT NULL, authorized INTEGER NOT NULL, evidence_ready INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS capture_project_links (
 capture_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, context_id TEXT NOT NULL,
 link_status TEXT NOT NULL CHECK(link_status IN ('candidate','confirmed','rejected')),
 source_id TEXT NOT NULL, artifact_version TEXT NOT NULL,
 FOREIGN KEY(capture_id) REFERENCES captures(id), FOREIGN KEY(project_id) REFERENCES projects(id)
);
CREATE TABLE IF NOT EXISTS derivations (
 id TEXT PRIMARY KEY, context_id TEXT NOT NULL, capture_id TEXT NOT NULL, processor TEXT NOT NULL,
 processor_version TEXT NOT NULL, basis_refs TEXT NOT NULL, why_text TEXT NOT NULL, created_at_ms INTEGER NOT NULL,
 FOREIGN KEY(capture_id) REFERENCES captures(id)
);
CREATE TABLE IF NOT EXISTS candidate_actions (
 id TEXT PRIMARY KEY, context_id TEXT NOT NULL, capture_id TEXT NOT NULL, derivation_id TEXT NOT NULL,
 candidate_text TEXT NOT NULL, candidate_state TEXT NOT NULL CHECK(candidate_state IN ('active','accepted','rejected','deferred')),
 created_at_ms INTEGER NOT NULL, FOREIGN KEY(derivation_id) REFERENCES derivations(id)
);
CREATE TABLE IF NOT EXISTS feedback (
 id INTEGER PRIMARY KEY AUTOINCREMENT, target_kind TEXT NOT NULL CHECK(target_kind IN ('capture_context','candidate_action','understanding')),
 target_id TEXT NOT NULL, context_id TEXT NOT NULL, decision TEXT NOT NULL,
 idem_key TEXT NOT NULL UNIQUE, detail TEXT NOT NULL, created_at_ms INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS actions (
 id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL UNIQUE, context_id TEXT NOT NULL,
 action_text TEXT NOT NULL, confirmation_kind TEXT NOT NULL CHECK(confirmation_kind IN ('accept','edit_accept')),
 action_state TEXT NOT NULL CHECK(action_state IN ('open','completed')), created_at_ms INTEGER NOT NULL,
 -- In this narrow slice an Action becomes confirmed atomically on creation.  The
 -- generated column makes that semantic mapping explicit and is the only Today
 -- ordering timestamp; action_id is the deterministic tie-break.
 confirmed_at_ms INTEGER GENERATED ALWAYS AS (created_at_ms) STORED,
 FOREIGN KEY(candidate_id) REFERENCES candidate_actions(id)
);
CREATE TABLE IF NOT EXISTS action_results (
 id TEXT PRIMARY KEY, action_id TEXT NOT NULL UNIQUE, result_kind TEXT NOT NULL CHECK(result_kind='completed'),
 result_text TEXT NOT NULL, idem_key TEXT NOT NULL UNIQUE, created_at_ms INTEGER NOT NULL,
 FOREIGN KEY(action_id) REFERENCES actions(id)
);
CREATE TABLE IF NOT EXISTS audit (
 id INTEGER PRIMARY KEY AUTOINCREMENT, event TEXT NOT NULL, target_id TEXT NOT NULL,
 created_at_ms INTEGER NOT NULL, detail TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS understandings (
 id TEXT PRIMARY KEY, context_id TEXT NOT NULL, capture_id TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE,
 page TEXT NOT NULL, selection_ref TEXT, removed_context_kinds TEXT NOT NULL,
 derivation_id TEXT NOT NULL UNIQUE,
 processor TEXT NOT NULL, processor_version TEXT NOT NULL, observation_text TEXT NOT NULL,
 suggestion_text TEXT NOT NULL, basis_refs TEXT NOT NULL, why_text TEXT NOT NULL,
 evidence_state TEXT NOT NULL CHECK(evidence_state='sufficient'), created_at_ms INTEGER NOT NULL,
 FOREIGN KEY(capture_id) REFERENCES captures(id)
);
PRAGMA user_version = 132;
"#;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct CaptureRequest { text: String, key: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct EmptyRequest {}
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ConfirmRequest { capture_id: String, context_id: String, decision: LinkDecision, idempotency_key: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ContextRequest { context_id: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NextDecisionRequest { candidate_id: String, decision: NextDecision, edited_text: Option<String>, idempotency_key: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ActionResultRequest { action_id: String, result: ActionResultKind, result_text: String, idempotency_key: String }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum GlobalPage { Today, ContextDetail }
impl GlobalPage { fn as_str(self) -> &'static str { match self { Self::Today => "today", Self::ContextDetail => "context_detail" } } }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum RemovedContextKind { PersonDetail, Page, Selection, Domain, Context, MemorySource }
impl RemovedContextKind { fn as_str(self) -> &'static str { match self { Self::PersonDetail => "person_detail", Self::Page => "page", Self::Selection => "selection", Self::Domain => "domain", Self::Context => "context", Self::MemorySource => "memory_source" } } }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct GlobalContextRequest { page: GlobalPage, selection_ref: Option<String>, removed_context_kinds: Option<Vec<RemovedContextKind>> }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct UnderstandingRequest { context_id: String, page: GlobalPage, selection_ref: Option<String>, removed_context_kinds: Option<Vec<RemovedContextKind>>, request_id: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct UnderstandingFeedbackRequest { understanding_id: String, decision: UnderstandingDecision, edited_text: Option<String>, idempotency_key: String }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum LinkDecision { Confirm, Reject }
impl LinkDecision { fn as_str(self) -> &'static str { match self { Self::Confirm => "confirm", Self::Reject => "reject" } } }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum NextDecision { Accept, EditAccept, Reject, Defer }
impl NextDecision { fn as_str(self) -> &'static str { match self { Self::Accept => "accept", Self::EditAccept => "edit_accept", Self::Reject => "reject", Self::Defer => "defer" } } }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum ActionResultKind { Completed }
impl ActionResultKind { fn as_str(self) -> &'static str { "completed" } }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum UnderstandingDecision { Confirm, EditConfirm, Reject, Correct, Ignore }
impl UnderstandingDecision { fn as_str(self) -> &'static str { match self { Self::Confirm => "confirm", Self::EditConfirm => "edit_confirm", Self::Reject => "reject", Self::Correct => "correct", Self::Ignore => "ignore" } } }

