#[derive(Debug, Serialize, Clone)]
struct GlobalAiContextResponse { context_id: String, page: String, selection_ref: Option<String>, included: Vec<ContextItem>, removed_context_kinds: Vec<String>, authorization_summary: Vec<String>, permissions: Vec<String>, evidence_status: String, request_local: bool }
#[derive(Debug, Serialize, Clone)]
struct UnderstandingView { understanding_id: String, observation: Option<String>, suggestion: Option<String>, identity: &'static str, processor: String, processor_version: String, basis_refs: Vec<String>, why: String, evidence_state: String, synthetic_adapter: bool, disclosure: Option<String> }
#[derive(Debug, Serialize, Clone)]
struct UnderstandingFeedbackResponse { status: String, feedback_id: String, understanding_id: String, decision: String, feedback_text: Option<String>, audit_event_count: usize }
