fn native_geometry(paths:&RuntimePaths,window:&tauri::Window,phase:&str,requested:&str)->Result<(),IpcError>{let path=geometry_path(paths,requested)?;regular_or_absent(&path,"geometry_type_rejected")?;let scale=window.scale_factor().map_err(|_|IpcError::blocked("native_geometry_unavailable","无法读取原生窗口比例。"))?;let inner=window.inner_size().map_err(|_|IpcError::blocked("native_geometry_unavailable","无法读取内容边界。"))?;let outer=window.outer_size().map_err(|_|IpcError::blocked("native_geometry_unavailable","无法读取窗口边界。"))?;let i=inner.to_logical::<f64>(scale);let o=outer.to_logical::<f64>(scale);let line=serde_json::json!({"task":"LIFEOS-P3-131","source":"actual-tauri-native-window","phase":phase,"requested_logical":requested,"scale_factor":scale,"content_bounds":{"size_physical":{"width":inner.width,"height":inner.height},"size_logical":{"width":i.width,"height":i.height}},"outer_bounds":{"size_physical":{"width":outer.width,"height":outer.height},"size_logical":{"width":o.width,"height":o.height}}});let mut f=OpenOptions::new().create(true).append(true).open(path).map_err(io_error)?;writeln!(f,"{line}").map_err(io_error)?;Ok(())}
